<section class="panel narrow-panel"><h2>Protege tu cuenta</h2><p class="text-secondary">Al cambiar tu contraseña se cerrarán tus sesiones abiertas.</p><?php if($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif ?><form method="post" action="<?= e(url('password')) ?>"><?= csrf_field() ?><?php foreach(['current'=>'Contraseña actual','password'=>'Nueva contraseña','confirmation'=>'Confirmar nueva contraseña'] as $name=>$label): ?><div class="mb-3"><label class="form-label" for="<?= $name ?>"><?= $label ?></label><input class="form-control" type="password" id="<?= $name ?>" name="<?= $name ?>" required <?= $name!=='current'?'minlength="12"':'' ?> maxlength="72" autocomplete="<?= $name==='current'?'current-password':'new-password' ?>"></div><?php endforeach ?><button class="btn btn-primary">Actualizar contraseña</button></form></section>
